'use client';

import { Bars3Icon, BellIcon, SunIcon, MoonIcon } from '@heroicons/react/24/outline';
import { useState } from 'react';
import { useTheme } from '@/hooks/use-theme';

interface HeaderProps {
  onMenuClick: () => void;
}

export default function Header({ onMenuClick }: HeaderProps) {
  const [showNotifications, setShowNotifications] = useState(false);

  return (
    <header className="bg-card shadow-sm border-b border-divider">
      <div className="flex items-center justify-between h-16 px-4">
        {/* Mobile menu button */}
        <button
          onClick={onMenuClick}
          className="lg:hidden p-2 rounded-lg text-text-secondary hover:text-primary hover:bg-surface transition-colors"
        >
          <Bars3Icon className="h-6 w-6" />
        </button>

        {/* Page Title */}
        <div className="flex-1">
          <h1 className="text-xl font-semibold text-primary">Dashboard</h1>
        </div>

        {/* Right side actions */}
        <div className="flex items-center space-x-4">
          {/* Notifications */}
          <div className="relative">
            <button
              onClick={() => setShowNotifications(!showNotifications)}
              className="p-2 rounded-full text-text-secondary hover:text-primary hover:bg-surface transition-colors relative"
            >
              <BellIcon className="h-6 w-6" />
              <span className="absolute top-0 right-0 h-2 w-2 bg-error rounded-full"></span>
            </button>
            
            {showNotifications && (
              <div className="absolute right-0 mt-2 w-80 bg-card rounded-lg shadow-lg border border-divider z-50">
                <div className="p-4 border-b border-divider">
                  <h3 className="text-sm font-medium text-primary">Notifications</h3>
                </div>
                <div className="max-h-96 overflow-y-auto">
                  <div className="p-4 border-b border-divider hover:bg-surface transition-colors cursor-pointer">
                    <div className="flex items-start">
                      <div className="flex-shrink-0">
                        <div className="h-2 w-2 bg-warning rounded-full mt-2"></div>
                      </div>
                      <div className="ml-3">
                        <p className="text-sm text-primary">Low stock alert</p>
                        <p className="text-xs text-text-secondary">Product XYZ is running low on stock</p>
                        <p className="text-xs text-text-secondary mt-1">2 hours ago</p>
                      </div>
                    </div>
                  </div>
                  <div className="p-4 hover:bg-surface transition-colors cursor-pointer">
                    <div className="flex items-start">
                      <div className="flex-shrink-0">
                        <div className="h-2 w-2 bg-success rounded-full mt-2"></div>
                      </div>
                      <div className="ml-3">
                        <p className="text-sm text-primary">Transfer completed</p>
                        <p className="text-xs text-text-secondary">Stock transfer from Branch A to Branch B</p>
                        <p className="text-xs text-text-secondary mt-1">5 hours ago</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* User menu */}
          <div className="flex items-center space-x-3">
            <div className="text-right">
              <p className="text-sm font-medium text-primary">Admin User</p>
              <p className="text-xs text-text-secondary">admin@pos.com</p>
            </div>
            <div className="h-8 w-8 bg-surface border border-divider rounded-full flex items-center justify-center">
              <span className="text-sm font-medium text-primary">AU</span>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}
