'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { CubeIcon, PlusIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';
import { formatCurrency, formatDate } from '@/lib/utils';

// Mock data for development
const mockProducts = [
  {
    id: '1',
    name: 'Wireless Mouse Pro',
    sku: 'WMP-001',
    description: 'Ergonomic wireless mouse with precision tracking',
    category: 'Electronics',
    price: 29.99,
    cost: 15.50,
    unit: 'pieces',
    barcode: '1234567890123',
    min_stock_level: 10,
    is_active: true,
    created_at: '2024-01-15T10:30:00Z',
    updated_at: '2024-03-10T14:20:00Z',
  },
  {
    id: '2',
    name: 'Mechanical Keyboard',
    sku: 'MKB-002',
    description: 'RGB mechanical keyboard with blue switches',
    category: 'Electronics',
    price: 89.99,
    cost: 45.00,
    unit: 'pieces',
    barcode: '2345678901234',
    min_stock_level: 5,
    is_active: true,
    created_at: '2024-02-01T09:15:00Z',
    updated_at: '2024-03-05T11:30:00Z',
  },
  {
    id: '3',
    name: 'USB-C Cable',
    sku: 'CAB-003',
    description: 'High-speed USB-C charging cable',
    category: 'Accessories',
    price: 12.99,
    cost: 3.99,
    unit: 'pieces',
    min_stock_level: 50,
    is_active: false,
    created_at: '2024-01-20T13:45:00Z',
    updated_at: '2024-02-28T16:45:00Z',
  },
];

export default function ProductsPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredProducts, setFilteredProducts] = useState(mockProducts);

  useEffect(() => {
    const filtered = mockProducts.filter(product =>
      product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredProducts(filtered);
  }, [searchTerm]);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-primary">Products</h1>
              <p className="mt-1 text-sm text-text-secondary">
                Manage your product catalog and inventory
              </p>
            </div>
            <button className="btn-primary">
              <PlusIcon className="h-5 w-5 mr-2" />
              Add Product
            </button>
          </div>

          {/* Search */}
          <div className="card p-4">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-5 w-5 text-text-secondary" />
              </div>
              <input
                type="text"
                placeholder="Search products..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input-field w-full pl-10"
              />
            </div>
          </div>

          {/* Products Table */}
          <div className="card overflow-hidden">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-divider">
                <thead className="bg-surface">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Product
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      SKU
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Category
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Price
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Stock Level
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Status
                    </th>
                    <th className="relative px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      <span>Actions</span>
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-card divide-y divide-divider">
                  {filteredProducts.map((product) => (
                    <tr key={product.id} className="hover:bg-surface">
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="flex items-center">
                          <CubeIcon className="h-8 w-8 text-text-secondary mr-3" />
                          <div>
                            <div className="text-sm font-medium text-primary">{product.name}</div>
                            <div className="text-xs text-text-secondary">{product.sku}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-text-secondary">
                        {product.category}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-text-secondary">
                        {formatCurrency(product.price)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                          product.is_active ? 'status-success' : 'status-error'
                        }`}>
                          {product.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-left text-sm">
                        <button className="text-primary hover:bg-primary/10 p-1 rounded transition-colors">
                          <PlusIcon className="h-4 w-4" />
                        </button>
                        <button className="text-text-secondary hover:bg-surface p-1 rounded transition-colors ml-2">
                          <CubeIcon className="h-4 w-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {filteredProducts.length === 0 && (
            <div className="text-center py-12">
              <CubeIcon className="h-12 w-12 text-text-secondary mx-auto mb-4" />
              <h3 className="text-lg font-medium text-primary mb-2">No products found</h3>
              <p className="text-text-secondary">Try adjusting your search criteria</p>
            </div>
          )}
        </div>
      </Layout>
    </AuthGuard>
  );
}
